   497                                          File Reading
   498  **************************************************************/
   499
   500  GF_EXPORT
   501  GF_ISOFile *gf_isom_open(const char *fileName, GF_ISOOpenMode OpenMode, const char *tmp_dir)
   502  {
   503          GF_ISOFile *movie;
   504          MP4_API_IO_Err = GF_OK;
   505
   506          switch (OpenMode & 0xFF) {
   507          case GF_ISOM_OPEN_READ_DUMP:
   508          case GF_ISOM_OPEN_READ:
   509                  movie = gf_isom_open_file(fileName, OpenMode, NULL);
   510                  break;
   511
   512  #ifndef GPAC_DISABLE_ISOM_WRITE
   513
   514          case GF_ISOM_OPEN_WRITE:
   515                  movie = gf_isom_create_movie(fileName, OpenMode, tmp_dir);
   516                  break;
   517          case GF_ISOM_OPEN_EDIT:
   518          case GF_ISOM_OPEN_READ_EDIT:
   519          case GF_ISOM_OPEN_KEEP_FRAGMENTS:
   520                  movie = gf_isom_open_file(fileName, OpenMode, tmp_dir);
   521                  break;
   522          case GF_ISOM_WRITE_EDIT:
   523                  movie = gf_isom_create_movie(fileName, OpenMode, tmp_dir);
   524                  break;
   525
   526  #endif /*GPAC_DISABLE_ISOM_WRITE*/
   527
   528          default:
   529                  return NULL;
   530          }
   531          return (GF_ISOFile *) movie;
   532  }
